$view=(string)($_GET['view']??'overview');if(!in_array($view,['overview','cohorts','students','lessons','material'],true))$view='overview';
function course_admin_url(int $activityId,int $courseId=0,string $view='overview',array $extra=[]): string {$args=['activity'=>$activityId];if($courseId>0){$args['course']=$courseId;$args['view']=$view;}return '/admin/courses.php?'.http_build_query($args+$extra);}
function course_admin_counts(PDO $db,int $courseId): array {
    $q=$db->prepare("SELECT
      (SELECT COUNT(*) FROM cms_form_submissions s WHERE s.course_id=:course AND s.status!='archived') registrations,
      (SELECT COUNT(*) FROM cms_form_submissions s WHERE s.course_id=:course AND s.status!='archived' AND (s.status='converted' OR s.payment_status='paid') AND s.cohort_id IS NULL) unassigned,
      (SELECT COUNT(*) FROM course_cohorts c WHERE c.course_id=:course AND c.status!='archived') cohorts,
      (SELECT COUNT(*) FROM course_enrollments e JOIN course_cohorts c ON c.id=e.cohort_id WHERE c.course_id=:course AND c.status!='archived' AND e.status='active') students,
      (SELECT COUNT(*) FROM course_lessons l WHERE l.course_id=:course) lessons,
      (SELECT COUNT(*) FROM course_material_pages m WHERE m.course_id=:course) materials");
    $q->execute(['course'=>$courseId]);return $q->fetch()?:['registrations'=>0,'unassigned'=>0,'cohorts'=>0,'students'=>0,'lessons'=>0,'materials'=>0];
}

if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    if(!verify_csrf('courses-admin',$_POST['_csrf']??null)){http_response_code(403);exit('Invalid request');}$action=(string)($_POST['action']??'');
    try{
        if($action==='create_from_page'){$created=course_create_from_page($db,(int)($_POST['public_page_id']??0),(int)($_POST['registration_form_id']??0));$courseId=(int)$created['id'];$view='overview';}
        elseif(!$course)throw new RuntimeException('Escolha um curso.');
        elseif($action==='update_course')course_update($db,(int)$course['id'],$_POST);
        elseif($action==='create_cohort')course_create_cohort_for_course($db,(int)$course['id'],(string)($_POST['title']??''),(string)($_POST['slug']??''),(string)($_POST['starts_at']??'')?:null,(string)($_POST['ends_at']??'')?:null);
        elseif($action==='add_lesson')course_add_lesson_for_course($db,(int)$course['id'],(string)($_POST['title']??''),(string)($_POST['lesson_key']??''));
        elseif($action==='set_release')course_set_lesson_release_for_course($db,(int)$course['id'],(int)($_POST['cohort_id']??0),(int)($_POST['lesson_id']??0),(string)($_POST['mode']??'block'),(string)($_POST['scheduled_at']??''));
        elseif($action==='add_material')course_material_add_page($db,(int)$course['id'],(int)($_POST['page_id']??0));
        elseif($action==='remove_material')course_material_remove_page($db,(int)$course['id'],(int)($_POST['page_id']??0));
        elseif($action==='map_section')course_material_set_section_lesson($db,(int)$course['id'],(int)($_POST['page_id']??0),(string)($_POST['section_key']??''),(int)($_POST['lesson_id']??0)?:null);
        else throw new RuntimeException('Ação inválida.');
        $_SESSION['admin_notice']='Alteração salva.';
    }catch(Throwable $e){$_SESSION['admin_notice']='Não foi possível concluir: '.$e->getMessage();}
    header('Location: '.course_admin_url($activityId,$courseId,$view),true,303);exit;
}

